import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import io.spring.application.CursorPager.Direction;
import io.spring.application.data.ArticleData;
import io.spring.application.data.ArticleFavoriteCount;
import io.spring.application.data.ProfileData;
import io.spring.core.user.User;
import io.spring.infrastructure.mybatis.readservice.ArticleFavoritesReadService;
import io.spring.infrastructure.mybatis.readservice.ArticleReadService;
import io.spring.infrastructure.mybatis.readservice.UserRelationshipQueryService;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import org.joda.time.DateTime;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
public class ArticleQueryServiceUnitTest {

  @Mock private ArticleReadService articleReadService;

  @Mock private UserRelationshipQueryService userRelationshipQueryService;

  @Mock private ArticleFavoritesReadService articleFavoritesReadService;

  @InjectMocks private ArticleQueryService articleQueryService;

  // GreyTest trace: findRecentArticlesWithCursor | STMT-1, IF-1-FALSE, IF-2-TRUE, IF-3-TRUE | BR-007 -> BR-008 -> BR-009 -> BR-010 -> TP-002 -> TC-1080
  @Test
  public void findRecentArticlesWithCursor_cutsReversesAndEnriches_whenPrevPageHasExtraIds() {
    // Arrange
    CursorPageParameter<DateTime> page =
        new CursorPageParameter<>(new DateTime(2000), 2, Direction.PREV);
    User currentUser = new User("reader@example.com", "reader", "secret", "bio", "image");
    ArticleData articleA1 =
        new ArticleData(
            "a1",
            "slug-1",
            "Tieu de 1",
            "Mo ta 1",
            "Noi dung 1",
            false,
            0,
            new DateTime(1000),
            new DateTime(1000),
            Arrays.asList("java"),
            new ProfileData("author1", "alice", "Bio 1", "image-1", false));
    ArticleData articleA2 =
        new ArticleData(
            "a2",
            "slug-2",
            "Tieu de 2",
            "Mo ta 2",
            "Noi dung 2",
            false,
            0,
            new DateTime(2000),
            new DateTime(2000),
            Arrays.asList("java"),
            new ProfileData("author2", "bob", "Bio 2", "image-2", false));
    when(articleReadService.findArticlesWithCursor(eq("java"), eq("alice"), eq("bob"), eq(page)))
        .thenReturn(new ArrayList<>(Arrays.asList("a1", "a2", "a3")));
    when(articleReadService.findArticles(eq(Arrays.asList("a2", "a1"))))
        .thenReturn(new ArrayList<>(Arrays.asList(articleA2, articleA1)));
    when(articleFavoritesReadService.articlesFavoriteCount(eq(Arrays.asList("a2", "a1"))))
        .thenReturn(
            Arrays.asList(new ArticleFavoriteCount("a2", 5), new ArticleFavoriteCount("a1", 4)));
    when(articleFavoritesReadService.userFavorites(eq(Arrays.asList("a2", "a1")), eq(currentUser)))
        .thenReturn(Collections.singleton("a2"));
    when(userRelationshipQueryService.followingAuthors(
            eq(currentUser.getId()), eq(Arrays.asList("author2", "author1"))))
        .thenReturn(Collections.singleton("author1"));

    // Act
    CursorPager<ArticleData> pager =
        articleQueryService.findRecentArticlesWithCursor("java", "alice", "bob", page, currentUser);

    // Assert
    verify(articleReadService).findArticles(eq(Arrays.asList("a2", "a1")));
    assertNotNull(pager);
    assertEquals(2, pager.getData().size());
    assertEquals("a2", pager.getData().get(0).getId());
    assertEquals("a1", pager.getData().get(1).getId());
    assertEquals(5, pager.getData().get(0).getFavoritesCount());
    assertTrue(pager.getData().get(0).isFavorited());
    assertEquals(4, pager.getData().get(1).getFavoritesCount());
    assertFalse(pager.getData().get(1).isFavorited());
    assertTrue(pager.getData().get(0).getProfileData().isFollowing());
    assertFalse(pager.getData().get(1).getProfileData().isFollowing());
    assertTrue(pager.hasPrevious());
    assertFalse(pager.hasNext());
  }
}

