    @Mock
    private UserRelationshipQueryService userRelationshipQueryService;

    @InjectMocks
    private CommentQueryService commentQueryService;

    // GreyTest trace: CommentQueryService.findById | IF-1-FALSE | BR-028 -> TP-025 -> TC-1128
    @Test
    void testFindById_UpdatesFollowingFlagFromRelationship() {
        // Arrange
        String id = "comment-1";
        User user = new User("reader@example.com", "reader", "secret", "", "");
        DateTime timestamp = new DateTime(2024, 1, 1, 10, 0, 0, DateTimeZone.UTC);
        CommentData commentData = new CommentData(
                id,
                "body-1",
                "article-1",
                timestamp,
                timestamp,
                new ProfileData("author-1", "alice", "bio-alice", "image-alice", false));
        when(commentReadService.findById(id)).thenReturn(commentData);
        when(userRelationshipQueryService.isUserFollowing(user.getId(), "author-1")).thenReturn(true);

        // Act
        Optional<CommentData> result = commentQueryService.findById(id, user);

        // Assert
        assertTrue(result.isPresent());
        assertSame(commentData, result.get());
        assertTrue(result.get().getProfileData().getFollowing());
        assertEquals("author-1", result.get().getProfileData().getId());
        verify(commentReadService, times(1)).findById(id);
        verify(userRelationshipQueryService, times(1)).isUserFollowing(user.getId(), "author-1");
